    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <ellipse cx=\"200\" cy=\"270\" rx=\"150\" ry=\"12\" fill=\"#e2e8f0\" opacity=\"0.6\"/>\n            \n            <!-- Raw Data Input -->\n            <g class=\"anim-data\">\n                <rect x=\"50\" y=\"80\" width=\"15\" height=\"15\" rx=\"2\" fill=\"var(--charcoal)\" opacity=\"0.5\"/>\n                <rect x=\"70\" y=\"60\" width=\"15\" height=\"15\" rx=\"2\" fill=\"var(--charcoal)\" opacity=\"0.5\"/>\n                <rect x=\"40\" y=\"110\" width=\"15\" height=\"15\" rx=\"2\" fill=\"var(--charcoal)\" opacity=\"0.5\"/>\n            </g>\n            <path class=\"anim-draw\" d=\"M80 100 Q120 100 140 140\" stroke=\"var(--charcoal)\" stroke-width=\"4\" stroke-dasharray=\"6 4\" fill=\"none\" opacity=\"0.4\"/>\n            \n            <!-- Processing Model / Engine -->\n            <rect class=\"anim-float\" x=\"140\" y=\"120\" width=\"120\" height=\"100\" rx=\"16\" fill=\"var(--primary-color)\"/>\n            <path class=\"anim-float\" d=\"M180 120 V220\" stroke=\"var(--charcoal)\" stroke-width=\"2\" opacity=\"0.2\"/>\n            <path class=\"anim-float\" d=\"M220 120 V220\" stroke=\"var(--charcoal)\" stroke-width=\"2\" opacity=\"0.2\"/>\n            <path class=\"anim-float\" d=\"M140 170 H260\" stroke=\"var(--charcoal)\" stroke-width=\"2\" opacity=\"0.2\"/>\n            \n            <!-- Nodes inside the model (Layers) -->\n            <g class=\"anim-pulse\">\n                <circle cx=\"160\" cy=\"145\" r=\"5\" fill=\"var(--secondary-color)\"/>\n                <circle cx=\"160\" cy=\"195\" r=\"5\" fill=\"var(--secondary-color)\"/>\n                <circle cx=\"200\" cy=\"170\" r=\"6\" fill=\"var(--accent-color)\"/>\n                <circle cx=\"240\" cy=\"145\" r=\"5\" fill=\"white\"/>\n                <circle cx=\"240\" cy=\"195\" r=\"5\" fill=\"white\"/>\n                <path d=\"M165 145 L195 170 M165 195 L195 170 M205 170 L235 145 M205 170 L235 195\" stroke=\"white\" stroke-width=\"2\" opacity=\"0.8\"/>\n            </g>\n\n            <!-- Output Pipeline -->\n            <path class=\"anim-draw\" d=\"M260 170 Q300 170 320 220\" stroke=\"var(--secondary-color)\" stroke-width=\"4\" stroke-dasharray=\"8 6\" fill=\"none\"/>\n            <path class=\"anim-draw\" d=\"M260 140 Q300 140 320 100\" stroke=\"var(--accent-color)\" stroke-width=\"4\" stroke-dasharray=\"8 6\" fill=\"none\"/>\n            \n            <!-- Sorted/Processed Data Output -->\n            <g class=\"anim-bounce\">\n                <!-- Cluster 1 (Organized, colored) -->\n                <rect x=\"315\" y=\"225\" width=\"20\" height=\"20\" rx=\"4\" fill=\"var(--secondary-color)\"/>\n                <rect x=\"340\" y=\"225\" width=\"20\" height=\"20\" rx=\"4\" fill=\"var(--secondary-color)\"/>\n                \n                <!-- Cluster 2 (Organized, colored) -->\n                <circle cx=\"330\" cy=\"90\" r=\"10\" fill=\"var(--accent-color)\"/>\n                <circle cx=\"355\" cy=\"80\" r=\"10\" fill=\"var(--accent-color)\"/>\n            </g>\n          </svg>"
