    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <g class=\"anim-float\">\n                <!-- Calendar Body -->\n                <rect x=\"120\" y=\"80\" width=\"160\" height=\"160\" rx=\"10\" fill=\"var(--bg-surface)\" stroke=\"var(--primary-color)\" stroke-width=\"4\"/>\n                \n                <!-- Calendar Header -->\n                <path d=\"M120 110 H280\" stroke=\"var(--primary-color)\" stroke-width=\"4\"/>\n                <path d=\"M120 90 C120 84 125 80 130 80 H270 C275 80 280 84 280 90 V110 H120 V90 Z\" fill=\"var(--primary-color)\"/>\n                \n                <!-- Ring Binders -->\n                <rect x=\"150\" y=\"60\" width=\"10\" height=\"30\" rx=\"5\" fill=\"var(--charcoal)\"/>\n                <rect x=\"240\" y=\"60\" width=\"10\" height=\"30\" rx=\"5\" fill=\"var(--charcoal)\"/>\n                <circle cx=\"155\" cy=\"90\" r=\"3\" fill=\"var(--bg-surface)\"/>\n                <circle cx=\"245\" cy=\"90\" r=\"3\" fill=\"var(--bg-surface)\"/>\n                \n                <!-- Grid / Days -->\n                <g opacity=\"0.1\" fill=\"var(--charcoal)\">\n                    <rect x=\"140\" y=\"130\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <rect x=\"170\" y=\"130\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <rect x=\"200\" y=\"130\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <rect x=\"230\" y=\"130\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    \n                    <rect x=\"140\" y=\"160\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <rect x=\"170\" y=\"160\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <rect x=\"200\" y=\"160\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <rect x=\"230\" y=\"160\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    \n                    <rect x=\"140\" y=\"190\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <!-- Event day -->\n                    <rect x=\"200\" y=\"190\" width=\"20\" height=\"20\" rx=\"2\"/>\n                    <rect x=\"230\" y=\"190\" width=\"20\" height=\"20\" rx=\"2\"/>\n                </g>\n                \n                <!-- Highlighted Event -->\n                <rect class=\"anim-pulse\" x=\"170\" y=\"190\" width=\"20\" height=\"20\" rx=\"4\" fill=\"var(--accent-color)\"/>\n                <circle class=\"anim-pulse\" cx=\"180\" cy=\"200\" r=\"4\" fill=\"var(--bg-surface)\"/>\n            </g>\n            \n            <!-- Floating Clock -->\n            <g class=\"anim-bounce\">\n                <circle cx=\"300\" cy=\"140\" r=\"30\" fill=\"var(--secondary-color)\"/>\n                <circle cx=\"300\" cy=\"140\" r=\"24\" fill=\"var(--bg-surface)\"/>\n                <g class=\"anim-rotate\" >\n                    <line x1=\"300\" y1=\"140\" x2=\"300\" y2=\"125\" stroke=\"var(--charcoal)\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n                </g>\n                <line x1=\"300\" y1=\"140\" x2=\"315\" y2=\"140\" stroke=\"var(--charcoal)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n                <circle cx=\"300\" cy=\"140\" r=\"3\" fill=\"var(--accent-color)\"/>\n            </g>\n          </svg>"
