    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <ellipse cx=\"200\" cy=\"270\" rx=\"140\" ry=\"10\" fill=\"#E2E8F0\" opacity=\"0.6\"/>\n            \n            <g class=\"anim-float\">\n                <!-- Gauge Outer Rim -->\n                <path d=\"M80 220 A 120 120 0 0 1 320 220\" stroke=\"var(--charcoal)\" stroke-width=\"40\" fill=\"none\" stroke-linecap=\"round\"/>\n                \n                <!-- Gauge Inner Colored Tracks -->\n                <!-- Red/Low Zone -->\n                <path d=\"M80 220 A 120 120 0 0 1 140 115\" stroke=\"var(--accent-color)\" stroke-width=\"38\" fill=\"none\" stroke-linecap=\"round\"/>\n                <!-- Yellow/Mid Zone -->\n                <path d=\"M140 115 A 120 120 0 0 1 260 115\" stroke=\"var(--secondary-color)\" stroke-width=\"38\" fill=\"none\"/>\n                <!-- Green/High Zone -->\n                <path d=\"M260 115 A 120 120 0 0 1 320 220\" stroke=\"var(--primary-color)\" stroke-width=\"38\" fill=\"none\" stroke-linecap=\"round\"/>\n                \n                <!-- Tick Marks Matrix -->\n                <path d=\"M85 220 H65 M315 220 H335 M200 105 V85 M120 135 L105 120 M280 135 L295 120\" stroke=\"var(--charcoal)\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n                \n                <g class=\"anim-bounce\">\n                    <!-- Gauge Needle (Animated to High Zone) -->\n                    <g class=\"anim-rotate\" style=\"transform-origin: 200px 220px; animation-duration: 3s;\">\n                        <!-- Pointing to top right -->\n                        <path d=\"M185 220 L280 140 L215 220 Z\" fill=\"var(--charcoal)\"/>\n                        <circle cx=\"200\" cy=\"220\" r=\"30\" fill=\"var(--bg-surface)\" stroke=\"var(--charcoal)\" stroke-width=\"8\"/>\n                        <circle cx=\"200\" cy=\"220\" r=\"10\" fill=\"var(--accent-color)\"/>\n                    </g>\n                </g>\n                \n                <!-- Score / Digital Display -->\n                <rect class=\"anim-pulse\" x=\"160\" y=\"250\" width=\"80\" height=\"30\" rx=\"5\" fill=\"var(--charcoal)\"/>\n                <path d=\"M185 265 H215 M185 270 H205\" stroke=\"var(--bg-surface)\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n            </g>\n          </svg>"
