    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <g style=\"animation-duration: 6s;\" class=\"anim-float\">\n                <!-- Wooden Plank (Base) -->\n                <rect x=\"100\" y=\"200\" width=\"200\" height=\"40\" rx=\"4\" fill=\"var(--bg-surface)\" stroke=\"var(--charcoal)\" stroke-width=\"8\"/>\n                <path d=\"M120 200 V240 M160 200 V240 M240 200 V240 M280 200 V240\" stroke=\"var(--charcoal)\" stroke-width=\"4\" opacity=\"0.3\"/>\n                <circle cx=\"140\" cy=\"220\" r=\"10\" stroke=\"var(--charcoal)\" stroke-width=\"2\" opacity=\"0.4\"/>\n                \n                <!-- Nail 1 (Driven in) -->\n                <path d=\"M180 200 V220\" stroke=\"var(--secondary-color)\" stroke-width=\"6\"/>\n                <rect x=\"170\" y=\"195\" width=\"20\" height=\"5\" fill=\"var(--charcoal)\"/>\n                \n                <!-- Nail 2 (Being hit) -->\n                <g transform=\"translate(240, 160)\">\n                    <g class=\"anim-bounce\" style=\"animation-duration: 4s;\">\n                        <path d=\"M0 0 V40\" stroke=\"var(--secondary-color)\" stroke-width=\"6\"/>\n                        <rect x=\"-10\" y=\"-5\" width=\"20\" height=\"5\" fill=\"var(--charcoal)\"/>\n                    </g>\n                </g>\n                \n                <!-- Hammer -->\n                <g transform=\"translate(240, 150)\">\n                    <g class=\"anim-rotate\" style=\"transform-origin: 60px -80px; animation-duration: 4s; animation-direction: alternate;\">\n                        <!-- Hammer Handle -->\n                        <rect x=\"10\" y=\"-120\" width=\"20\" height=\"100\" rx=\"10\" fill=\"var(--secondary-color)\" transform=\"rotate(25, 20, -70)\"/>\n                        <rect x=\"10\" y=\"-50\" width=\"20\" height=\"30\" rx=\"4\" fill=\"var(--charcoal)\" transform=\"rotate(25, 20, -70)\"/>\n                        <!-- Hammer Head -->\n                        <g transform=\"translate(-10, -50) rotate(-15)\">\n                            <path d=\"M-40 -10 H20 V10 H-40 Z\" fill=\"var(--primary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                            <!-- Claw -->\n                            <path d=\"M20 -10 Q50 -10 60 10 Q30 0 20 10 Z\" fill=\"var(--primary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                        </g>\n                        <!-- Impact Marks -->\n                        <g transform=\"translate(-20, 0)\">\n<g  style=\"animation-duration: 4s;\" class=\"anim-pulse\" opacity=\"0.6\">\n                            <line x1=\"-15\" y1=\"-15\" x2=\"-30\" y2=\"-30\" stroke=\"var(--accent-color)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n                            <line x1=\"15\" y1=\"-15\" x2=\"30\" y2=\"-30\" stroke=\"var(--accent-color)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n                        </g>\n</g>\n                    </g>\n                </g>\n            </g>\n          </svg>"
