    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <g class=\"anim-float\">\n                <!-- Level Body (Refined for meaningful tilt) -->\n                <g transform=\"translate(200, 150)\">\n                    <g class=\"anim-rotate\" style=\"transform-origin: center; animation-duration: 4s; animation-direction: alternate; animation-timing-function: ease-in-out; transform: rotate(-8deg);\">\n                        <rect x=\"-140\" y=\"-20\" width=\"280\" height=\"40\" rx=\"4\" fill=\"var(--secondary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"8\"/>\n                        <!-- End caps -->\n                        <rect x=\"-140\" y=\"-20\" width=\"20\" height=\"40\" rx=\"4\" fill=\"var(--charcoal)\"/>\n                        <rect x=\"120\" y=\"-20\" width=\"20\" height=\"40\" rx=\"4\" fill=\"var(--charcoal)\"/>\n                        \n                        <!-- Middle Vial (Horizontal) -->\n                        <rect x=\"-40\" y=\"-12\" width=\"80\" height=\"24\" rx=\"12\" fill=\"var(--bg-surface)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                        <rect x=\"-40\" y=\"-12\" width=\"80\" height=\"24\" rx=\"12\" fill=\"var(--accent-color)\" opacity=\"0.3\"/>\n                        <path d=\"M-15 -12 V12 M15 -12 V12\" stroke=\"var(--charcoal)\" stroke-width=\"2\" opacity=\"0.5\"/>\n                        \n                        <!-- Bubble (Moves in sync with tilt) -->\n                        <g class=\"anim-slide\" style=\"animation-duration: 4s; animation-direction: alternate; animation-timing-function: ease-in-out;\">\n                             <circle cx=\"0\" cy=\"0\" r=\"8\" fill=\"var(--bg-surface)\" stroke=\"var(--accent-color)\" stroke-width=\"2\"/>\n                        </g>\n                        \n                        <!-- Side Vials -->\n                        <circle cx=\"-90\" cy=\"0\" r=\"14\" fill=\"var(--bg-surface)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                        <circle cx=\"90\" cy=\"0\" r=\"14\" fill=\"var(--bg-surface)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                    </g>\n                </g>\n                <!-- Reference Line -->\n                <line x1=\"60\" y1=\"180\" x2=\"340\" y2=\"180\" stroke=\"var(--charcoal)\" stroke-width=\"2\" stroke-dasharray=\"4 4\" opacity=\"0.2\"/>\n            </g>\n          </svg>"
