    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <g style=\"animation-duration: 6s;\" class=\"anim-float\">\n                <!-- House Keychain Ornament -->\n                <g transform=\"translate(190, 80)\">\n                    <g class=\"anim-bounce\" style=\"animation-duration: 8s;\">\n                        <!-- Chain Link -->\n                        <circle cx=\"0\" cy=\"0\" r=\"10\" fill=\"none\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                        <circle cx=\"0\" cy=\"20\" r=\"10\" fill=\"none\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                        <!-- Keyring -->\n                        <circle cx=\"0\" cy=\"60\" r=\"30\" fill=\"none\" stroke=\"var(--accent-color)\" stroke-width=\"8\"/>\n                        \n                        <!-- House Charm -->\n                        <path d=\"M-30 0 L0 -30 L30 0 V30 H-30 Z\" fill=\"var(--primary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"6\" transform=\"translate(0, -50)\"/>\n                        <circle cx=\"0\" cy=\"-40\" r=\"5\" fill=\"var(--bg-surface)\"/>\n                        \n                        <!-- Key 1 (Silver/Secondary) -->\n                        <g transform=\"translate(-15, 80) rotate(15)\">\n                            <g class=\"anim-rotate\" style=\"transform-origin: 0px 0px; animation-duration: 6s; animation-direction: alternate;\">\n                                <circle cx=\"0\" cy=\"0\" r=\"15\" fill=\"var(--secondary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                                <rect x=\"-5\" y=\"15\" width=\"10\" height=\"60\" rx=\"2\" fill=\"var(--secondary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                                <rect x=\"5\" y=\"55\" width=\"15\" height=\"8\" rx=\"2\" fill=\"var(--secondary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                                <rect x=\"5\" y=\"40\" width=\"10\" height=\"8\" rx=\"2\" fill=\"var(--secondary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                            </g>\n                        </g>\n                        \n                        <!-- Key 2 (Gold/Primary) -->\n                        <g transform=\"translate(15, 80) rotate(-15)\">\n                            <g class=\"anim-rotate\" style=\"transform-origin: 0px 0px; animation-duration: 8s; animation-direction: alternate-reverse;\">\n                                <circle cx=\"0\" cy=\"0\" r=\"15\" fill=\"var(--primary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                                <rect x=\"-5\" y=\"15\" width=\"10\" height=\"70\" rx=\"2\" fill=\"var(--primary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                                <rect x=\"-20\" y=\"65\" width=\"15\" height=\"10\" rx=\"2\" fill=\"var(--primary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                                <rect x=\"-15\" y=\"45\" width=\"10\" height=\"8\" rx=\"2\" fill=\"var(--primary-color)\" stroke=\"var(--charcoal)\" stroke-width=\"4\"/>\n                            </g>\n                        </g>\n                    </g>\n                </g>\n                \n                <!-- Ribbon (Grand Opening) -->\n                <path style=\"animation-duration: 4s;\" class=\"anim-draw\" d=\"M60 260 Q200 180 340 260\" stroke=\"var(--accent-color)\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.5\"/>\n            </g>\n          </svg>"
