    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <ellipse cx=\"200\" cy=\"270\" rx=\"140\" ry=\"10\" fill=\"#E2E8F0\" opacity=\"0.6\"/>\n            \n            <!-- Open Book Base -->\n            <path class=\"anim-float\" d=\"M100 240 Q150 220 200 240 Q250 220 300 240 L280 260 Q240 250 200 260 Q160 250 120 260 Z\" fill=\"var(--secondary-color)\" opacity=\"0.3\"/>\n            <path class=\"anim-bounce\" d=\"M120 220 Q160 200 200 220 L200 180 Q160 160 120 180 Z\" fill=\"var(--primary-color)\"/>\n            <path class=\"anim-bounce\" style=\"animation-delay: -0.2s\" d=\"M280 220 Q240 200 200 220 L200 180 Q240 160 280 180 Z\" fill=\"var(--primary-color)\" opacity=\"0.8\"/>\n            <path d=\"M130 190 Q160 175 190 190 M130 200 Q160 185 190 200 M130 210 Q160 195 190 210\" stroke=\"white\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.5\"/>\n            <path d=\"M210 190 Q240 175 270 190 M210 200 Q240 185 270 200 M210 210 Q240 195 270 210\" stroke=\"white\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.5\"/>\n\n            <!-- Quill Feather -->\n            <path class=\"anim-float\" style=\"animation-delay:-1s\" d=\"M240 180 Q280 120 290 60 Q260 80 240 130 Q220 100 240 180 Z\" fill=\"var(--accent-color)\"/>\n            <path class=\"anim-float\" style=\"animation-delay:-1s\" d=\"M240 180 Q270 120 290 60\" stroke=\"var(--charcoal)\" stroke-width=\"2\" fill=\"none\"/>\n            <path class=\"anim-draw\" d=\"M240 180 Q220 230 160 240\" stroke=\"var(--accent-color)\" stroke-width=\"3\" stroke-dasharray=\"4 4\" fill=\"none\"/>\n            \n            <!-- Tragedy (Left) -->\n            <g transform=\"translate(140, 100) rotate(-15)\">\n                <g class=\"anim-float\">\n                    <ellipse cx=\"0\" cy=\"0\" rx=\"30\" ry=\"40\" fill=\"var(--charcoal)\"/>\n                    <ellipse cx=\"0\" cy=\"0\" rx=\"25\" ry=\"35\" fill=\"var(--primary-color)\"/>\n                    <path d=\"M-10 -10 Q-5 -15 0 -10 M10 -10 Q5 -15 0 -10\" stroke=\"var(--charcoal)\" stroke-width=\"2\" fill=\"none\"/>\n                    <circle cx=\"-10\" cy=\"0\" r=\"3\" fill=\"var(--charcoal)\"/>\n                    <circle cx=\"10\" cy=\"0\" r=\"3\" fill=\"var(--charcoal)\"/>\n                    <path d=\"M-10 15 Q0 5 10 15\" stroke=\"var(--charcoal)\" stroke-width=\"3\" fill=\"none\"/>\n                </g>\n            </g>\n            \n            <!-- Comedy (Right) -->\n            <g transform=\"translate(190, 80) rotate(15)\">\n                <g class=\"anim-float\" style=\"animation-delay: -0.5s\">\n                    <ellipse cx=\"0\" cy=\"0\" rx=\"30\" ry=\"40\" fill=\"var(--charcoal)\"/>\n                    <ellipse cx=\"0\" cy=\"0\" rx=\"25\" ry=\"35\" fill=\"#F8FAFC\"/>\n                    <path d=\"M-10 -15 Q-5 -20 0 -15 M10 -15 Q5 -20 0 -15\" stroke=\"var(--primary-color)\" stroke-width=\"2\" fill=\"none\"/>\n                    <circle cx=\"-10\" cy=\"-5\" r=\"3\" fill=\"var(--primary-color)\"/>\n                    <circle cx=\"10\" cy=\"-5\" r=\"3\" fill=\"var(--primary-color)\"/>\n                    <path d=\"M-10 10 Q0 25 10 10\" stroke=\"var(--primary-color)\" stroke-width=\"3\" fill=\"none\"/>\n                </g>\n            </g>\n            \n            <!-- Magical sparkles -->\n            <circle class=\"anim-glow\" cx=\"120\" cy=\"80\" r=\"4\" fill=\"var(--accent-color)\"/>\n            <circle class=\"anim-glow\" cx=\"280\" cy=\"140\" r=\"5\" fill=\"var(--secondary-color)\"/>\n            <circle cx=\"210\" cy=\"40\" r=\"3\" fill=\"var(--accent-color)\"/>\n          </svg>"
