    "svg": "<svg viewBox=\"0 0 400 300\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <!-- Ground / street -->\n            <rect x=\"0\" y=\"240\" width=\"400\" height=\"60\" fill=\"var(--charcoal)\" opacity=\"0.06\"/>\n\n            <!-- Rainbow banner -->\n            <g class=\"anim-float\" style=\"animation-duration: 4s;\">\n              <line x1=\"80\" y1=\"50\" x2=\"80\" y2=\"120\" stroke=\"var(--charcoal)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n              <line x1=\"320\" y1=\"50\" x2=\"320\" y2=\"120\" stroke=\"var(--charcoal)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n              <!-- Banner stripes -->\n              <path d=\"M80 55 H320 V70 H80 Z\" fill=\"#FF0018\"/>\n              <path d=\"M80 70 H320 V83 H80 Z\" fill=\"#FFA52C\"/>\n              <path d=\"M80 83 H320 V96 H80 Z\" fill=\"#FFFF41\"/>\n              <path d=\"M80 96 H320 V109 H80 Z\" fill=\"#008018\"/>\n              <path d=\"M80 109 H320 V122 H80 Z\" fill=\"#0000F9\"/>\n              <!-- Banner text -->\n              <text x=\"200\" y=\"94\" font-family=\"sans-serif\" font-weight=\"bold\" font-size=\"14\" fill=\"white\" text-anchor=\"middle\" letter-spacing=\"1\" opacity=\"0.95\">PRIDE</text>\n            </g>\n\n            <!-- Crowd of figures (stylised, diverse) -->\n            <!-- Figure 1 - left, red top -->\n            <g transform=\"translate(80, 170)\">\n              <g class=\"anim-bounce\" style=\"animation-duration: 6s;\">\n                <circle cx=\"0\" cy=\"-40\" r=\"16\" fill=\"#F5CBA7\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M-15 -24 Q-15 20 -20 50 H20 Q15 20 15 -24 Z\" fill=\"#FF0018\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <!-- Left arm raised with flag -->\n                <path d=\"M-15 -10 Q-35 -30 -40 -50\" stroke=\"#F5CBA7\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n                <rect x=\"-42\" y=\"-68\" width=\"18\" height=\"12\" fill=\"#FF0018\"/>\n                <rect x=\"-42\" y=\"-56\" width=\"18\" height=\"8\" fill=\"#FFFF41\"/>\n                <rect x=\"-42\" y=\"-48\" width=\"18\" height=\"8\" fill=\"#0000F9\"/>\n                <line x1=\"-42\" y1=\"-68\" x2=\"-42\" y2=\"-40\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n              </g>\n            </g>\n\n            <!-- Figure 2 - center-left, purple top -->\n            <g transform=\"translate(145, 195)\">\n              <g class=\"anim-bounce\" style=\"animation-duration: 5s; animation-delay: -1s;\">\n                <circle cx=\"0\" cy=\"-40\" r=\"14\" fill=\"#FDBCB4\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M-13 -26 Q-12 15 -15 45 H15 Q12 15 13 -26 Z\" fill=\"#86007D\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M13 -10 Q30 -20 35 -10\" stroke=\"#FDBCB4\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n                <path d=\"M-13 -10 Q-28 5 -30 20\" stroke=\"#FDBCB4\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n              </g>\n            </g>\n\n            <!-- Figure 3 - center, teal top -->\n            <g transform=\"translate(210, 180)\">\n              <g class=\"anim-bounce\" style=\"animation-duration: 7s; animation-delay: -2s;\">\n                <circle cx=\"0\" cy=\"-45\" r=\"18\" fill=\"#D4956A\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M-16 -27 Q-15 20 -18 55 H18 Q15 20 16 -27 Z\" fill=\"#008098\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <!-- Both arms up -->\n                <path d=\"M-16 -15 Q-38 -35 -42 -55\" stroke=\"#D4956A\" stroke-width=\"11\" stroke-linecap=\"round\"/>\n                <path d=\"M16 -15 Q38 -35 42 -55\" stroke=\"#D4956A\" stroke-width=\"11\" stroke-linecap=\"round\"/>\n              </g>\n            </g>\n\n            <!-- Figure 4 - center-right, yellow top -->\n            <g transform=\"translate(275, 190)\">\n              <g class=\"anim-bounce\" style=\"animation-duration: 6s; animation-delay: -3s;\">\n                <circle cx=\"0\" cy=\"-40\" r=\"14\" fill=\"#F5CBA7\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M-13 -26 Q-12 15 -15 45 H15 Q12 15 13 -26 Z\" fill=\"#FFA52C\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M13 -12 Q32 -5 36 10\" stroke=\"#F5CBA7\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n              </g>\n            </g>\n\n            <!-- Figure 5 - right, blue top -->\n            <g transform=\"translate(330, 175)\">\n              <g class=\"anim-bounce\" style=\"animation-duration: 5s; animation-delay: -1.5s;\">\n                <circle cx=\"0\" cy=\"-40\" r=\"16\" fill=\"#FDBCB4\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M-14 -24 Q-14 20 -18 50 H18 Q14 20 14 -24 Z\" fill=\"#0000F9\" stroke=\"var(--charcoal)\" stroke-width=\"2\"/>\n                <path d=\"M-14 -10 Q-35 -25 -39 -48\" stroke=\"#FDBCB4\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n              </g>\n            </g>\n\n            <!-- Confetti / dots floating -->\n            <g class=\"anim-pulse\" style=\"animation-duration: 2s;\">\n              <circle cx=\"110\" cy=\"145\" r=\"5\" fill=\"#FF0018\" opacity=\"0.7\"/>\n              <circle cx=\"185\" cy=\"130\" r=\"4\" fill=\"#FFFF41\" opacity=\"0.7\"/>\n              <circle cx=\"250\" cy=\"140\" r=\"5\" fill=\"#008018\" opacity=\"0.7\"/>\n              <circle cx=\"300\" cy=\"135\" r=\"3\" fill=\"#0000F9\" opacity=\"0.7\"/>\n              <circle cx=\"355\" cy=\"148\" r=\"4\" fill=\"#86007D\" opacity=\"0.7\"/>\n            </g>\n          </svg>"
